// Spot objective at pitch x 0.0, z -0.4, then the matching text
CMND_BTL_SET_PURPOSE(2, 9, true, 0, 0.0, -0.40000001);
CMND_BTL_SET_PURPOSETEXT(true, "purpose_021", "para_cp0009");

// Line objective at pitch z -0.4, marker gv9999a
CMND_BTL_SET_PURPOSE(3, -1, true, 0, -0.40000001, 0);
CMND_BTL_SET_PURPOSETEXT(true, "purpose_130");

// Marker with para_cp0009's face; the character to reach is para_cp0010
CMND_BTL_SET_PURPOSE(1, 9, true, 0, 10);
CMND_BTL_SET_PURPOSETEXT(true, "purpose_120", "para_cp0009");

// Called by the engine when the current objective is reached
CallPurposeMarker <- function ()
{
	if (eventCounter == 0)
	{
		RunEv44020010();
		eventCounter++;
	}
	// ... next beats ...
};
